// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// Local to this test: every case here posts a RAW body whose shape is the thing
// under test (a missing key, a wrongly-typed value). Routing those through the
// shared createCoupon helper's dataOverride map would normalise exactly the
// malformation being asserted, so this helper sends the body verbatim.
async function createCouponWithRawBody(
    client: SkyrampClient,
    headers: Record<string, string>,
    body: string,
    expectedStatus: number
) {
    // Execute Request
    const response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/coupons",
        method: "POST",
        body: body,
        headers: headers
    });

    // Generated Assertions
    expect(response.statusCode, 'status code').toBe(expectedStatus);

    return response;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Codes that must be ACCEPTED are made run-unique so the file is re-runnable;
    // the deliberately invalid code values are sent verbatim.
    const baseCode = uniqueSuffix("TESTBOT-VAL-BASE");
    const codeA = uniqueSuffix("TESTBOT-VAL-A");
    const codeB = uniqueSuffix("TESTBOT-VAL-B");
    const codeC = uniqueSuffix("TESTBOT-VAL-C");
    const codeD = uniqueSuffix("TESTBOT-VAL-D");
    const codeE = uniqueSuffix("TESTBOT-VAL-E");
    const codeF = uniqueSuffix("TESTBOT-VAL-F");

    // A well-formed body is accepted — the baseline the rejections are measured against.
    const couponsPostResponse = await createCouponWithRawBody(client, headers, `{
        "code": "${baseCode}",
        "discountPercent": 25
    }`, 201);
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(baseCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(25);
    expect(getResponseValue(couponsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(couponsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    // code omitted entirely
    const couponsPost1Response = await createCouponWithRawBody(client, headers, `{
        "discountPercent": 25
    }`, 400);
    expect(couponsPost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost1Response, "response"), 'error message').toBe("A valid coupon code is required.");
    expect(getResponseValue(couponsPost1Response, "response.id"), 'no coupon is created').toBeNull();

    // empty code
    const couponsPost2Response = await createCouponWithRawBody(client, headers, `{
        "code": "",
        "discountPercent": 25
    }`, 400);
    expect(couponsPost2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost2Response, "response"), 'error message').toBe("A valid coupon code is required.");
    expect(getResponseValue(couponsPost2Response, "response.id"), 'no coupon is created').toBeNull();

    // whitespace-only code
    const couponsPost3Response = await createCouponWithRawBody(client, headers, `{
        "code": "   ",
        "discountPercent": 25
    }`, 400);
    expect(couponsPost3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost3Response, "response"), 'error message').toBe("A valid coupon code is required.");
    expect(getResponseValue(couponsPost3Response, "response.id"), 'no coupon is created').toBeNull();

    // non-string code
    const couponsPost4Response = await createCouponWithRawBody(client, headers, `{
        "code": 12345,
        "discountPercent": 25
    }`, 400);
    expect(couponsPost4Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost4Response, "response"), 'error message').toBe("A valid coupon code is required.");
    expect(getResponseValue(couponsPost4Response, "response.id"), 'no coupon is created').toBeNull();

    // discountPercent sent as a string rather than a number
    const couponsPost5Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeA}",
        "discountPercent": "50"
    }`, 400);
    expect(couponsPost5Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost5Response, "response"), 'error message').toBe("discountPercent must be a number between 0 and 100.");
    expect(getResponseValue(couponsPost5Response, "response.id"), 'no coupon is created').toBeNull();

    // discountPercent one below the lower bound
    const couponsPost6Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeB}",
        "discountPercent": -1
    }`, 400);
    expect(couponsPost6Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost6Response, "response"), 'error message').toBe("discountPercent must be a number between 0 and 100.");
    expect(getResponseValue(couponsPost6Response, "response.id"), 'no coupon is created').toBeNull();

    // discountPercent one above the upper bound
    const couponsPost7Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeC}",
        "discountPercent": 101
    }`, 400);
    expect(couponsPost7Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost7Response, "response"), 'error message').toBe("discountPercent must be a number between 0 and 100.");
    expect(getResponseValue(couponsPost7Response, "response.id"), 'no coupon is created').toBeNull();

    // lower boundary value 0 — must be accepted
    const couponsPost8Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeD}",
        "discountPercent": 0
    }`, 201);
    expect(couponsPost8Response.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPost8Response, "response.code"), 'code').toBe(codeD);
    expect(getResponseValue(couponsPost8Response, "response.discountPercent"), 'lower boundary discountPercent is stored').toBe(0);
    expect(getResponseValue(couponsPost8Response, "response.id"), 'id').toBeGreaterThan(0);

    // upper boundary value 100 — must be accepted
    const couponsPost9Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeE}",
        "discountPercent": 100
    }`, 201);
    expect(couponsPost9Response.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPost9Response, "response.code"), 'code').toBe(codeE);
    expect(getResponseValue(couponsPost9Response, "response.discountPercent"), 'upper boundary discountPercent is stored').toBe(100);
    expect(getResponseValue(couponsPost9Response, "response.id"), 'id').toBeGreaterThan(0);

    // fractional discountPercent — the Int column cannot store it, so it must be
    // refused as client input rather than crashing the handler.
    const couponsPost10Response = await createCouponWithRawBody(client, headers, `{
        "code": "${codeF}",
        "discountPercent": 12.5
    }`, 400);
    expect(couponsPost10Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost10Response, "response"), 'error message').toBe("discountPercent must be a number between 0 and 100.");
    expect(getResponseValue(couponsPost10Response, "response.id"), 'no coupon is created').toBeNull();
});
